Given an integer array arr[], print kth distinct element in this array. The given array may contain duplicates and the output should print the k-th element among all unique elements. If k is more than the number of distinct elements, print -1.Examples:Input: arr[] = {1, 2, 1, 3, 4, 2},  k = 2Output: 4Explanation: The First non-repeating element is 3 and the Second non-repeating element is 4Input: {2, 2, 2, 2},  k = 2Output: -1Explanation: There is no distinct (non-repeating) element in the array. Input: arr[] = {1, 2, 50, 10, 20, 2}, k = 3Output: TheFirst non-repeating element is 1 and the Second non-repeating element is 10. Try It YourselfTable of Content[Naive Approach] Using Nested Loop – O(n^2) Time and O(1) Space[Expected Approach] Using Hashing – O(n) Time and O(n) Space[Naive Approach] Using Nested Loop – O(n^2) Time and O(1) SpaceThe idea is to use two nested loops where the outer loop picks elements from left to right, and the inner loop checks if the picked element is present somewhere else. If not present, then increment the count of distinct elements. If the count becomes k, return the current element.
            C++

    #include <bits/stdc++.h>
using namespace std;

int kthDistinct(vector<int> arr, 
                              int k)
{
    int dist_count = 0, n = arr.size();
    for (int i = 0; i < n; i++)
    {
        // Check if current element is
        // present somewhere else.
        int j;
        for (j = 0; j < n; j++)
            if (i != j && arr[j] == arr[i])
                break;

        // If element is unique
        if (j == n)
            dist_count++;

        if (dist_count == k)
            return arr[i];
    }

    return -1;
}


int main ()
{
    vector<int> arr = {1, 2, 1, 3, 4, 2};
    int k = 2;
    cout << kthDistinct(arr, k);
    return 0;
}


