            C++

    #include <bits/stdc++.h>
using namespace std;

int kthDistinct(vector<int> arr, int k)
{ 
    // Traverse input array and 
    // store counts if individual 
    // elements.
    int n = arr.size(); 
    unordered_map<int, int> h;
    for (int i = 0; i < n; i++)
        h[arr[i]]++;

    // If size of hash is
    // less than k.
    if (h.size() < k)
        return -1;

    // Traverse array again and 
    // find k-th element with 
    // count as 1.
    int dist_count = 0;
    for (int i = 0; i < n; i++)
    {
        if (h[arr[i]] == 1)
            dist_count++;
        if (dist_count == k)
            return arr[i];
    }

    return -1;
}

