     using System;
using System.Collections.Generic;

class GfG 
{

// Returns k-th distinct 
// element in arr. 
static int kthDistinct(int []arr, int k) 
{ 
    int n = arr.Length; 
    Dictionary<int, int> h = new Dictionary<int, int>();
    for (int i = 0; i < n; i++) 
    {
        if(h.ContainsKey(arr[i]))
        {
            var val = h[arr[i]];
            h.Remove(arr[i]);
            h.Add(arr[i], val + 1); 

        }     
        else
            h.Add(arr[i], 1);
    }

    // If size of hash is 
    // less than k. 
    if (h.Count < k) 
        return -1; 

    // Traverse array again and 
    // find k-th element with 
    // count as 1. 
    int dist_count = 0; 
    for (int i = 0; i < n; i++) 
    { 
        if (h[arr[i]] == 1) 
            dist_count++; 
        if (dist_count == k) 
            return arr[i]; 
    } 
    return -1; 
} 

